from collections import defaultdict

access_token = gmail_access_token
categories = [
    apis.gmail.show_inbox_threads,
    apis.gmail.show_outbox_threads,
    apis.gmail.show_archived_threads,
    apis.gmail.show_spam_threads,
    apis.gmail.show_snoozed_threads,
    apis.gmail.show_starred_threads,
]

label_names = ['priority-1','priority-2','priority-3','P1','P2']

def fetch_ids_by_label(label_name, page_limit=20):
    ids=set()
    for api_fn in categories:
        page_index=0
        while True:
            resp = api_fn(access_token=access_token, label=label_name, page_index=page_index, page_limit=page_limit)
            if not resp:
                break
            for item in resp:
                ids.add(item['email_thread_id'])
            page_index += 1
    return ids

results = {}
for ln in label_names:
    ids = fetch_ids_by_label(ln)
    results[ln] = {'count': len(ids), 'ids_sample': sorted(ids)[:20]}

print('Verification label counts:', results)
